  let petsData = null, petsFetching = false, petsListSig = '', petsFetchAt = 0;
  let petFCat = -1, petFStatus = 0, petFSearch = '';   // cat -1=all/0-2 ; status 0=all/1=obtained/2=locked
  // Owned = single bit (vp[v]>>>b & 1), or a value >= th over the bit range [b..hi]
  // (e.g. Tiny Death = reaper-task count >= 200). b < 0 => untracked (null).
  function petOwned(p, vp) {
    if (p.b < 0) return null;
    const raw = (vp[p.v] || 0) >>> 0;
    if (p.th) { const w = (p.hi || p.b) - p.b + 1, mask = w >= 32 ? 0xffffffff : ((1 << w) - 1); return ((raw >>> p.b) & mask) >= p.th; }
    return !!((raw >>> p.b) & 1);
  }
  async function fetchPets(force) {
    if (!bridge() || petsFetching) return;
    const _t = Date.now(); if (!force && _t - petsFetchAt < 2000) return; petsFetchAt = _t;   // obtained data changes slowly
    petsFetching = true;
    try {
      let vp = {};
      if (bridge().varps) { try { vp = JSON.parse(await bridge().varps(myPid(), PET_VARPS.join(','))); } catch (e) {} }
      // An empty read must keep the last good state; otherwise every pet flips to "locked".
      if (!vp || !Object.keys(vp).length) return;
      petsData = PETS.map(p => ({ ...p, owned: petOwned(p, vp) }));   // null = untracked (legacy pets, no unlock bit)
    } finally { petsFetching = false; }
    paneRun('pets', renderPets);
  }
  function renderPets() {
    const c = $('content');
    let wrap = $('petsWrap');
    if (!wrap) {
      c.innerHTML = ''; petsListSig = '';   // reset the sig or the fresh wrap never populates
      wrap = document.createElement('div'); wrap.id = 'petsWrap'; wrap.className = 'pk-wrap'; c.appendChild(wrap);
      const tb = document.createElement('div'); tb.className = 'pet-toolbar';
      const mkchip = (label, grp, val, cur) => { const b = document.createElement('button'); b.className = 'pet-chip' + (val === cur ? ' on' : ''); b.textContent = label; b.dataset.grp = grp; b.dataset.val = val; return b; };
      const catRow = document.createElement('div'); catRow.className = 'pet-chips';
      catRow.appendChild(mkchip('All', 'cat', -1, petFCat));
      PET_CATS.forEach((nm, i) => catRow.appendChild(mkchip(nm, 'cat', i, petFCat)));
      const stRow = document.createElement('div'); stRow.className = 'pet-chips';
      ['All', 'Obtained', 'Locked'].forEach((nm, i) => stRow.appendChild(mkchip(nm, 'st', i, petFStatus)));
      const search = document.createElement('input'); search.className = 'pet-search'; search.id = 'petSearch'; search.placeholder = 'Search pet or boss...'; search.value = petFSearch;
      tb.appendChild(catRow); tb.appendChild(stRow); tb.appendChild(search); wrap.appendChild(tb);
      const cnt = document.createElement('div'); cnt.id = 'petCnt'; cnt.className = 'pet-count'; wrap.appendChild(cnt);
      const list = document.createElement('div'); list.id = 'petsList'; list.className = 'pet-list'; wrap.appendChild(list);
      tb.addEventListener('click', e => {
        const b = e.target.closest('.pet-chip'); if (!b) return;
        if (b.dataset.grp === 'cat') petFCat = +b.dataset.val; else petFStatus = +b.dataset.val;
        tb.querySelectorAll('.pet-chip[data-grp="' + b.dataset.grp + '"]').forEach(x => x.classList.toggle('on', x === b));
        petsListSig = ''; renderPetList();
      });
      search.addEventListener('input', () => { petFSearch = search.value.toLowerCase(); petsListSig = ''; renderPetList(); });
    }
    renderPetList();
  }
  function renderPetList() {
    const list = $('petsList'); if (!list) return;
    const d = petsData;
    if (!d) { list.innerHTML = '<div class="empty">Reading... (be in-world)</div>'; petsListSig = ''; return; }
    const items = d.filter(p =>
      (petFCat < 0 || p.c === petFCat) &&
      (petFStatus === 0 || (petFStatus === 1 ? p.owned === true : p.owned === false)) &&
      (!petFSearch || p.n.toLowerCase().indexOf(petFSearch) >= 0 || (p.s && p.s.toLowerCase().indexOf(petFSearch) >= 0)));
    items.sort((a, b) => a.c - b.c || a.n.localeCompare(b.n));
    const got = d.filter(p => p.owned === true).length;
    const unt = d.filter(p => p.owned === null).length;
    const cnt = $('petCnt'); if (cnt) cnt.textContent = got + ' / ' + (d.length - unt) + ' obtained' + (unt ? '  ·  ' + unt + ' untracked' : '') + (items.length !== d.length ? '  ·  ' + items.length + ' shown' : '');
    const sig = petFCat + '|' + petFStatus + '|' + petFSearch + '|' + items.map(p => p.n + (p.owned === true ? '1' : p.owned === false ? '0' : '-')).join(',');
    if (sig === petsListSig) return;
    petsListSig = sig;
    list.innerHTML = '';
    if (!items.length) { list.innerHTML = '<div class="empty">No pets match.</div>'; return; }
    let _lastCat = -1;
    for (const p of items) {
      if (p.c !== _lastCat) {
        _lastCat = p.c;
        const hdr = document.createElement('div'); hdr.className = 'pet-cat-hdr';
        const ncat = items.reduce((k, x) => k + (x.c === p.c ? 1 : 0), 0);
        hdr.innerHTML = PET_CATS[p.c] + ' <span class="pc-n">' + ncat + '</span>';
        list.appendChild(hdr);
      }
      const status = p.owned === true ? 'obtained' : p.owned === false ? 'locked' : 'untracked';
      const row = document.createElement('div'); row.className = 'pet-row' + (status === 'locked' ? ' pet-locked' : '');
      const src = p.b < 0
        ? 'Source: not tracked (no unlock bit in game data)'
        : 'Source: varp ' + p.v + (p.th
            ? ' bits ' + p.b + '-' + (p.hi || p.b) + ' (obtained when ≥ ' + p.th + ')'
            : ' bit ' + p.b);
      row.dataset.tip = p.n + '\n' + (p.s || 'Unlock method unknown.') + '\n' +
        (status === 'obtained' ? 'Status: obtained' : status === 'locked' ? 'Status: not obtained'
         : 'Status: not tracked (legacy pet - no obtained flag in game data; check it in the Pets interface).') +
        '\n' + src;
      const ico = document.createElement('div'); ico.className = 'pet-ico';
      { const u = PET_ICON_URL[p.n] || (p.ic ? resolveIcon(p.ic) : ''); if (u) ico.innerHTML = '<img src="' + u + '">'; }
      row.appendChild(ico);
      if (p.si >= 0) { const sk = document.createElement('div'); sk.className = 'pet-skico sk-icon'; sk.dataset.skill = p.si; attachSkillIcon(sk, p.si); row.appendChild(sk); }
      const info = document.createElement('div'); info.className = 'pet-info';
      const nm = document.createElement('div'); nm.className = 'pet-nm'; nm.textContent = p.n; info.appendChild(nm);
      row.appendChild(info);   // the unlock method lives in the hover tooltip, not inline
      const st = document.createElement('div');
      st.className = 'pet-st ' + (status === 'obtained' ? 'pet-yes' : status === 'locked' ? 'pet-no' : 'pet-na');
      st.textContent = status === 'obtained' ? 'Obtained' : status === 'locked' ? 'Locked' : 'Untracked';
      row.appendChild(st);
      list.appendChild(row);
    }
  }
